result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/wfc.py", "content": """"Tiny wave-function-collapse: SEA (~), COAST (+), LAND (#).

Adjacency rules (orthogonal neighbors only):
  SEA-SEA, SEA-COAST, COAST-COAST, COAST-LAND, LAND-LAND allowed.
  SEA never touches LAND.
"""

import random

SEA, COAST, LAND = "SEA", "COAST", "LAND"
SYMBOLS = {SEA: "~", COAST: "+", LAND: "#"}

# Allowed neighbor pairs in both directions
ALLOWED = {
    frozenset((SEA, SEA)),
    frozenset((SEA, COAST)),
    frozenset((COAST, COAST)),
    frozenset((COAST, LAND)),
    frozenset((LAND, LAND)),
}

TILES = [SEA, COAST, LAND]


def _neighbors(y, x, h, w):
    if y > 0:
        yield y - 1, x
    if y < h - 1:
        yield y + 1, x
    if x > 0:
        yield y, x - 1
    if x < w - 1:
        yield y, x + 1


def _compatible(a, b):
    return frozenset((a, b)) in ALLOWED


def collapse(width=20, height=20, seed=0, max_restarts=50):
    """Collapse a width x height grid. Returns list of rows of tile names.

    Minimum-entropy cell selection with seeded RNG; restarts on contradiction,
    bounded to max_restarts attempts (raises RuntimeError if all fail).
    """
    for attempt in range(max_restarts):
        rng = random.Random((seed, attempt))
        result = _attempt(width, height, rng)
        if result is not None:
            return result
    raise RuntimeError(f"wfc failed after {max_restarts} restarts (seed={seed})")


def _attempt(w, h, rng):
    # domains[y][x] = set of possible tiles; None means collapsed
    domains = [[set(TILES) for _ in range(w)] for _ in range(h)]
    collapsed = [[None] * w for _ in range(h)]
    remaining = h * w

    while remaining > 0:
        # Pick uncollapsed cell with minimum entropy (fewest candidates),
        # breaking ties randomly.
        best = None
        best_size = None
        cells = [
            (y, x)
            for y in range(h)
            for x in range(w)
            if collapsed[y][x] is None
        ]
        rng.shuffle(cells)
        for cell in cells:
            size = len(domains[cell[0]][cell[1]])
            if size == 0:
                return None  # contradiction
            if best_size is None or size < best_size:
                best = cell
                best_size = size
                if size == 1:
                    break

        y, x = best
        choice = rng.choice(sorted(domains[y][x]))
        collapsed[y][x] = choice
        domains[y][x] = {choice}
        remaining -= 1

        # Propagate: repeatedly prune neighbors' domains.
        stack = [(y, x)]
        while stack:
            cy, cx = stack.pop()
            tile = collapsed[cy][cx]
            for ny, nx in _neighbors(cy, cx, h, w):
                if collapsed[ny][nx] is not None:
                    continue
                pruned = {t for t in domains[ny][nx] if _compatible(t, tile)}
                if len(pruned) < len(domains[ny][nx]):
                    domains[ny][nx] = pruned
                    if not pruned:
                        return None  # contradiction -> restart
                    if len(pruned) == 1:
                        collapsed[ny][nx] = next(iter(pruned))
                        remaining -= 1
                        stack.append((ny, nx))
    return collapsed


def render(grid):
    """Render a grid of tile names as ASCII art."""
    return "\n".join("".join(SYMBOLS[t] for t in row) for row in grid)


def check_grid(grid):
    """Return list of violations of the adjacency rules."""
    h, w = len(grid), len(grid[0])
    bad = []
    for y in range(h):
        for x in range(w):
            for ny, nx in _neighbors(y, x, h, w):
                if (ny, nx) <= (y, x):
                    continue  # each pair once
                if not _compatible(grid[y][x], grid[ny][nx]):
                    bad.append(((y, x), (ny, nx)))
    return bad


if __name__ == "__main__":
    grid = collapse(seed=1)
    print(render(grid))
