from wfc import COAST, LAND, SEA, check_grid, collapse


def test_no_violations_seeds_1_to_20():
    for seed in range(1, 21):
        grid = collapse(seed=seed)
        assert check_grid(grid) == [], f"seed {seed} has violations"


def test_deterministic_same_seed():
    for seed in range(1, 21):
        assert collapse(seed=seed) == collapse(seed=seed), f"seed {seed} differs"


def test_some_seed_has_all_three_tiles():
    tiles_seen = set()
    for seed in range(1, 21):
        grid = collapse(seed=seed)
        tiles_seen.update(t for row in grid for t in row)
        if {SEA, COAST, LAND} <= tiles_seen:
            return
    pytest.fail(f"no seed produced all three tiles; saw {tiles_seen}")
